reg('data4', 'd_tf', d => {
  const { labels, vals } = dataSet(Math.max(2, d), true), mx = Math.max(...vals), mn = Math.min(...vals), sum = vals.reduce((s, x) => s + x, 0);
  const fig = tableHtml(['День', ...labels.slice(0, 5)], [['Посетители', ...vals]]).replace('<th>День</th>', '<th></th>');
  const [i, j] = R.sample([...labels.keys()], 2), diff = vals[i] - vals[j];
  const st = [
    [`Больше всего посетителей — в «${labels[vals.indexOf(mx)]}».`, true], [`Меньше всего посетителей — в «${labels[(vals.indexOf(mn) + 1) % labels.length]}».`, false],
    [`В «${labels[i]}» посетителей на ${Math.abs(diff)} ${diff > 0 ? 'больше' : 'меньше'}, чем в «${labels[j]}».`, true],
    [`В «${labels[i]}» посетителей на ${Math.abs(diff) + 10} ${diff > 0 ? 'больше' : 'меньше'}, чем в «${labels[j]}».`, false],
    [`Всего за ${labels.length} дней пришло ${sum} ${pl(sum, 'посетитель', 'посетителя', 'посетителей')}.`, true], [`Всего за ${labels.length} дней пришло ${sum + 10} ${pl(sum + 10, 'посетитель', 'посетителя', 'посетителей')}.`, false],
    [`В каждый день посетителей было больше ${mn - 5}.`, true], [`В каждый день посетителей было больше ${mn}.`, false]
  ];
  for (let t = 0; t < 20; t++) {
    const pick = R.sample(st, 4), ans = pick.filter(x => x[1]).map(x => x[0]);
    if (!ans.length || ans.length === 4 || new Set(pick.map(x => x[0])).size < 4) continue;
    return { q: 'Отметь все <b>верные</b> утверждения по таблице.', fig, type: 'multi', items: pick.map(x => x[0]), answer: ans, wide: true,
      hint: 'Проверь каждое утверждение отдельно по числам из таблицы.', explain: pick.map(x => `${x[1] ? '✓ Верно' : '✗ Неверно'}: ${x[0]}`) };
  }
  return null;
});
reg('data4', 'd_logic', d => {
  const v = d === 1 ? R.int(1, 2) : d === 2 ? R.int(1, 3) : R.int(2, 4);
  if (v === 1) {   /* сумма и разность */
    const small = R.int(3, d === 1 ? 15 : 40), diff = R.int(2, d === 1 ? 10 : 30), big = small + diff;
    const [a, b, u] = R.pick([['Кот', 'собака', 'кг'], ['Книга', 'альбом', 'р.']]);
    return { q: `${a} и ${b} вместе ${u === 'кг' ? 'весят' : 'стоят'} ${small + big} ${u}. ${b[0].toUpperCase() + b.slice(1)} на ${diff} ${u} ${u === 'кг' ? 'тяжелее' : 'дороже'}. Сколько ${u === 'кг' ? 'весит' : 'стоит'} ${a.toLowerCase()}?`, type: 'num', answer: small, draft: true,
      traps: [[(small + big) / 2 === Math.floor((small + big) / 2) ? (small + big) / 2 : null, 'Если разделить поровну, они были бы одинаковыми. А один на ' + diff + ' больше.'], [big, 'Это второй, а спрашивают про первого.']],
      hint: `Убери разницу: ${small + big} − ${diff} — это два одинаковых «меньших». Раздели на 2.`, explain: [`1) ${small + big} − ${diff} = ${2 * small}.`, `2) ${2 * small} : 2 = ${small} (${u}).`, `Проверка: ${small} + ${big} = ${small + big} ✓`] };
  }
  if (v === 2) {   /* головы и ноги */
    const ch = R.int(2, 9), rb = R.int(2, 9), heads = ch + rb, legs = 2 * ch + 4 * rb;
    return { q: `Во дворе куры и кролики. Всего ${heads} ${pl(heads, 'голова', 'головы', 'голов')} и ${legs} ${pl(legs, 'нога', 'ноги', 'ног')}. Сколько кроликов?`, type: 'num', answer: rb, draft: true,
      traps: [[ch, 'Это куры. Спрашивают про кроликов.']], hint: `Пусть все были бы курами: ног было бы ${heads} · 2. Каждый кролик добавляет ещё 2 ноги.`,
      explain: [`1) ${heads} · 2 = ${2 * heads} — если бы все были курами.`, `2) ${legs} − ${2 * heads} = ${legs - 2 * heads} — «лишние» ноги.`, `3) ${legs - 2 * heads} : 2 = ${rb} — кроликов.`] };
  }
  if (v === 3) {   /* возраст */
    const s = R.int(5, 12), k = R.int(3, 5), m = s * k, y = R.int(2, 10);
    return { q: `Сыну ${s} лет, а мама в ${k} раза старше. Сколько лет будет маме через ${y} ${pl(y, 'год', 'года', 'лет')}?`.replace(`в ${k} раза`, `в ${k} ${pl(k, 'раз', 'раза', 'раз')}`), type: 'num', answer: m + y,
      traps: [[m, `Это сколько маме сейчас. Через ${y} ${pl(y, 'год', 'года', 'лет')} будет больше.`], [s + k + y, '«В … раза старше» — это умножение.']],
      hint: 'Сначала найди, сколько лет маме сейчас.', explain: [`1) ${s} · ${k} = ${m} (лет) — маме сейчас.`, `2) ${m} + ${y} = ${m + y} (лет).`] };
  }
  /* распил бревна / столбы */
  const n = R.int(3, 12), cut = R.chance(0.5);
  return cut
    ? { q: `Бревно распилили на ${n} частей. Сколько сделали распилов?`, type: 'num', answer: n - 1, traps: [[n, 'Одним распилом получаем 2 части. Распилов на 1 меньше, чем частей.']],
      hint: 'Нарисуй: 1 распил — 2 части, 2 распила — 3 части…', explain: [`Распилов на 1 меньше, чем частей: ${n} − 1 = ${n - 1}.`] }
    : { q: `Вдоль дорожки длиной ${(n - 1) * 5} м поставили столбики через каждые 5 м, считая начало и конец. Сколько столбиков?`, type: 'num', answer: n,
      traps: [[n - 1, 'Промежутков ' + (n - 1) + ', а столбиков на 1 больше (есть столбик в начале).']], hint: 'Посчитай промежутки, потом прибавь 1.',
      explain: [`${(n - 1) * 5} : 5 = ${n - 1} — промежутков.`, `${n - 1} + 1 = ${n} — столбиков.`] };
});
